create or replace function public.business_rewards_analytics(p_business_id uuid,p_start timestamptz default now()-interval '30 days',p_end timestamptz default now()) returns jsonb language sql security definer set search_path=public,pg_temp as $$ with c as(select ci.id,coalesce(ci.points_awarded,0) points_awarded from check_ins ci join locations l on l.id=ci.location_id where l.business_id=p_business_id and ci.checked_in_at between p_start and p_end) select jsonb_build_object('check_ins',(select count(*) from c),'points_awarded',(select coalesce(sum(points_awarded),0) from c),'reward_events',(select count(*) from c where points_awarded>0),'reward_points',(select coalesce(sum(points_awarded),0) from c)); $$;
